-- =======================================================================
-- V5__seed_from_jex_dev_20260422.sql
--
-- Seeds login-related rows copied from JEX DEV (wecmsvndevdb) on 2026-04-22.
-- Scope: active users + tenants they belong to + active USER_BUSI_CONN_INFM links.
--
-- Rules this migration respects (per user directive 2026-04-22):
--   * No DROP / no TRUNCATE / no schema recreation — additive only.
--   * Idempotent — ON CONFLICT DO NOTHING on every block. Safe to re-apply
--     (though Flyway only runs each versioned migration once).
--   * USER_PW is intentionally the DataSeeder sentinel '__BCRYPT_PENDING__'.
--     The ApplicationRunner at startup (local profile) replaces the sentinel
--     with bcrypt("Password!1") on first run. Legacy USER_PW hashes (PostgreSQL
--     hash() output) are NOT usable with Spring's BCryptPasswordEncoder.
--   * LANG_CD was not stored on legacy USER_INFM, so 'EN' is used for every
--     imported user.
--
-- Counts at generation time:
--   BUSI_INFM           : 218 rows
--   USER_INFM           : 318 rows
--   USER_BUSI_CONN_INFM : 382 rows
--
-- Manual credentials after first startup (any imported user):
--   USER_ID = <any email above>
--   USER_PW = Password!1
-- =======================================================================

-- --------------------------------------------------------------------- tenants
ON CONFLICT (BIZ_KEY) DO NOTHING;

-- --------------------------------------------------------------------- users
ON CONFLICT (USER_ID) DO NOTHING;

-- --------------------------------------------------------------------- user-biz links
ON CONFLICT (USER_ID, BIZ_KEY) DO NOTHING;
